CREATE DATABASE IF NOT EXISTS safenation_disaster_link CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE safenation_disaster_link;
CREATE TABLE roles (name VARCHAR(32) PRIMARY KEY, label VARCHAR(80) NOT NULL);
INSERT INTO roles VALUES ('citizen','Citizen'),('authority','Authority'),('responder','Emergency response team'),('volunteer','Volunteer'),('facility_manager','Facility manager'),('admin','Administrator');
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'citizen', phone VARCHAR(30) NOT NULL DEFAULT '', area VARCHAR(100) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role) REFERENCES roles(name));
CREATE TABLE disaster_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE);
INSERT INTO disaster_types(name) VALUES ('Flood'),('Landslide'),('Storm'),('Fire'),('Heavy rainfall'),('Other');
CREATE TABLE reports (address VARCHAR(255) NOT NULL DEFAULT '', id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, type_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, description TEXT NOT NULL, area VARCHAR(100) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, occurred_at DATETIME NOT NULL, affected_people INT UNSIGNED NOT NULL DEFAULT 0, damage VARCHAR(30) NOT NULL DEFAULT 'none', ai_severity VARCHAR(16) NOT NULL, ai_reason TEXT NOT NULL, severity VARCHAR(16) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', response_status VARCHAR(30) NOT NULL DEFAULT 'monitoring', duplicate_of INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(type_id) REFERENCES disaster_types(id), FOREIGN KEY(duplicate_of) REFERENCES reports(id), INDEX(status,severity), INDEX(type_id,created_at), INDEX(area));
CREATE TABLE report_reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, report_id INT UNSIGNED NOT NULL, reviewer_id INT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL, severity VARCHAR(16) NOT NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(report_id) REFERENCES reports(id), FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE alerts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, author_id INT UNSIGNED NOT NULL, type_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, area VARCHAR(100) NOT NULL, severity VARCHAR(16) NOT NULL, published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NULL, active BOOLEAN NOT NULL DEFAULT 1, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(type_id) REFERENCES disaster_types(id), INDEX(active,expires_at));
CREATE TABLE facilities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, manager_id INT UNSIGNED NULL, kind VARCHAR(20) NOT NULL, name VARCHAR(150) NOT NULL, area VARCHAR(100) NOT NULL, address VARCHAR(255) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, capacity INT UNSIGNED NOT NULL DEFAULT 0, occupancy INT UNSIGNED NOT NULL DEFAULT 0, services TEXT NOT NULL, phone VARCHAR(30) NOT NULL, emergency_service BOOLEAN NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'open', capacity_known BOOLEAN NOT NULL DEFAULT 1, source_code VARCHAR(100) NULL UNIQUE, source_url VARCHAR(255) NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(manager_id) REFERENCES users(id), INDEX(kind,status,area));
CREATE TABLE assistance_requests (address VARCHAR(255) NOT NULL DEFAULT '', id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, assigned_to INT UNSIGNED NULL, category VARCHAR(40) NOT NULL, description TEXT NOT NULL, area VARCHAR(100) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, people INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'submitted', note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(assigned_to) REFERENCES users(id), INDEX(status));
CREATE TABLE volunteers (user_id INT UNSIGNED PRIMARY KEY, skills VARCHAR(255) NOT NULL, experience TEXT NOT NULL, availability VARCHAR(30) NOT NULL, service_area VARCHAR(100) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE volunteer_assignments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, volunteer_id INT UNSIGNED NOT NULL, report_id INT UNSIGNED NULL, coordinator_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, instructions TEXT NOT NULL, area VARCHAR(100) NOT NULL, due_at DATETIME NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'assigned', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(volunteer_id) REFERENCES volunteers(user_id), FOREIGN KEY(report_id) REFERENCES reports(id), FOREIGN KEY(coordinator_id) REFERENCES users(id));
CREATE TABLE resources (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(40) NOT NULL, unit VARCHAR(30) NOT NULL, location VARCHAR(100) NOT NULL, quantity DECIMAL(12,2) UNSIGNED NOT NULL DEFAULT 0, minimum_quantity DECIMAL(12,2) UNSIGNED NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE resource_transactions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resource_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, kind VARCHAR(20) NOT NULL, quantity DECIMAL(12,2) UNSIGNED NOT NULL, destination VARCHAR(150) NOT NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(resource_id) REFERENCES resources(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, link VARCHAR(200) NOT NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id,read_at));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(40) NOT NULL, entity_id INT UNSIGNED NULL, detail TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(created_at));
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fingerprint CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(fingerprint,created_at));
CREATE TABLE settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES ('site_name','SafeNation'),('announcement','Our project includes labelled example records. Hospital directory availability must be confirmed with the hospital.');
